+            <span className="inline-flex items-center gap-1 rounded bg-muted/30 px-1.5 py-0.5 text-[9.5px] text-muted-foreground/70">
+              {scenario.id}
+            </span>
+          </div>
+        </div>
+        {selected && <ChevronRight size={11} className="mt-0.5 shrink-0 text-primary" />}
+      </div>
