+// ─── Run output panel ───────────────────────────────────────────────────────
+
+function extractNoVncUrl(text: string): string | null {
+  const m = text.match(/https?:\/\/[^\s]*vnc\.html[^\s]*/);
+  return m ? m[0] : null;
