+        .flatten()
+        .collect();
+
+        for candidate in &candidates {
+            match templates.get_template(candidate).await {
+                Ok(_) => return Ok(candidate.clone()),
+                Err(e) => {
+                    tracing::warn!(
+                        candidate = %candidate,
+                        error = %e,
+                        "template candidate failed validation, trying next"
+                    );
+                }
+            }
+        }
+
+        // 2. store_item_id → match by image_info
